/**
 * Figma Make Project Detector
 *
 * Detects if a project was generated by Figma Make based on:
 * - React + Vite + TypeScript stack (98% accuracy)
 * - Component-based structure with CSS modules
 * - Typical Figma design-to-code patterns
 *
 * Extends BaseDetector for common functionality
 */

import path from 'path';
import { BaseDetector } from './base-detector.js';

export class FigmaDetector extends BaseDetector {
  priority = 4; // Lower priority than V0 (priority 3)
  tool = 'figma';

  /**
   * Detect Figma Make projects with comprehensive analysis
   *
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{tool: string|null, confidence: number, evidence: string[], metadata: Object}>}
   */
  async detect(projectRoot) {
    const evidence = [];
    let confidence = 0.0;

    // Check package.json for Figma Make signatures
    const pkgConfidence = await this.checkPackageJson(projectRoot);
    confidence += pkgConfidence.score;
    evidence.push(...pkgConfidence.evidence);

    // Check project structure
    const structConfidence = await this.checkProjectStructure(projectRoot);
    confidence += structConfidence.score;
    evidence.push(...structConfidence.evidence);

    // Check build configuration
    const buildConfidence = await this.checkBuildConfiguration(projectRoot);
    confidence += buildConfidence.score;
    evidence.push(...buildConfidence.evidence);

    // Check CSS module patterns
    const cssConfidence = await this.checkCSSModules(projectRoot);
    confidence += cssConfidence.score;
    evidence.push(...cssConfidence.evidence);

    // Normalize confidence to 0-1 range
    // Maximum achievable confidence is ~4.0 across all checks
    const normalizedConfidence = Math.min(confidence / 4.0, 1.0);

    // Detect UI library for metadata
    const pkg = await this.readPackageJson(projectRoot);
    const uiLibrary = this.detectUILibrary(pkg);

    return {
      tool: normalizedConfidence >= 0.45 ? this.tool : null,
      confidence: normalizedConfidence,
      evidence,
      metadata: {
        framework: 'react-vite',
        buildTool: 'vite',
        typescript: true,
        uiLibrary,
        buildOutputDir: await this.detectBuildOutputDir(projectRoot)
      }
    };
  }

  /**
   * Check package.json for Figma Make signatures
   *
   * @private
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{score: number, evidence: string[]}>}
   */
  async checkPackageJson(projectRoot) {
    const evidence = [];
    let score = 0;

    const pkg = await this.readPackageJson(projectRoot);
    if (!pkg) {
      return { score: 0, evidence: ['package.json not found'] };
    }

    const deps = { ...pkg.dependencies, ...pkg.devDependencies };

    // Check for React (nearly always present)
    if (pkg.dependencies?.react) {
      score += 0.3;
      evidence.push(`React v${pkg.dependencies.react} detected`);
    }

    // Check for Vite (strong Figma Make indicator)
    if (deps.vite) {
      score += 0.8;
      evidence.push(`Vite v${deps.vite} detected (primary build tool)`);
    }

    // Check for TypeScript (98% of Figma Make projects)
    const hasTypeScript =
      deps.typescript || Object.keys(deps).some(d => d.includes('@types/'));

    if (hasTypeScript) {
      score += 0.7;
      evidence.push('TypeScript configured');
    }

    // React + Vite + TypeScript = 98% accuracy signature
    if (pkg.dependencies?.react && deps.vite && hasTypeScript) {
      score += 0.9; // Boost confidence for complete stack
      evidence.push('React + Vite + TypeScript stack detected (98% Figma confidence)');
    }

    // Check for UI libraries (common in Figma exports)
    const uiLibraries = [
      '@mui/material',
      'antd',
      '@chakra-ui/react',
      '@mantine/core',
      'react-bootstrap',
      'tailwindcss'
    ];

    const hasUILibrary = uiLibraries.some(lib => deps[lib]);
    if (hasUILibrary) {
      score += 0.4;
      evidence.push(`UI library detected (${this.detectUILibrary(pkg)})`);
    }

    // Check dev scripts for Vite
    if (pkg.scripts?.dev?.includes('vite')) {
      score += 0.2;
      evidence.push('Vite dev script configured');
    }

    return { score: Math.min(score, 1.0), evidence };
  }

  /**
   * Check for typical Figma Make project structure
   *
   * @private
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{score: number, evidence: string[]}>}
   */
  async checkProjectStructure(projectRoot) {
    const evidence = [];
    let score = 0;

    // Check for src/ directory (standard for Figma exports)
    const srcDir = path.join(projectRoot, 'src');
    const hasSrc = await this.dirExists(srcDir);

    if (hasSrc) {
      score += 0.3;
      evidence.push('src/ directory found (standard Figma structure)');

      // Check for src/components/ (design-first component organization)
      const componentsDir = path.join(srcDir, 'components');
      const hasComponents = await this.dirExists(componentsDir);

      if (hasComponents) {
        score += 0.6;
        evidence.push('src/components/ directory found (component-based design)');

        // Check for CSS modules (Figma export style)
        const componentFiles = await this.listFiles(componentsDir);
        const cssModules = componentFiles.filter(f => f.endsWith('.module.css'));

        if (cssModules.length > 0) {
          score += 0.5;
          evidence.push(`CSS Modules detected (${cssModules.length} files)`);
        }
      }

      // Check for other common Figma directory structure
      const hasApp = await this.fileExists(path.join(srcDir, 'App.tsx')) ||
                     await this.fileExists(path.join(srcDir, 'App.jsx'));
      const hasMain = await this.fileExists(path.join(srcDir, 'main.tsx')) ||
                      await this.fileExists(path.join(srcDir, 'main.jsx'));

      if (hasApp && hasMain) {
        score += 0.4;
        evidence.push('Typical React entry point structure (App.tsx + main.tsx)');
      }
    }

    // Check for public/ directory (asset management)
    const publicDir = path.join(projectRoot, 'public');
    const hasPublic = await this.dirExists(publicDir);

    if (hasPublic) {
      score += 0.2;
      evidence.push('public/ directory found (asset management)');
    }

    return { score: Math.min(score, 1.0), evidence };
  }

  /**
   * Check for Vite build configuration
   *
   * @private
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{score: number, evidence: string[]}>}
   */
  async checkBuildConfiguration(projectRoot) {
    const evidence = [];
    let score = 0;

    // Check for vite.config.ts or vite.config.js
    const viteConfigTs = path.join(projectRoot, 'vite.config.ts');
    const viteConfigJs = path.join(projectRoot, 'vite.config.js');

    const hasViteConfig = (await this.fileExists(viteConfigTs)) ||
                          (await this.fileExists(viteConfigJs));

    if (hasViteConfig) {
      score += 0.8;
      evidence.push('vite.config.ts/js found');
    }

    // Check for tsconfig.json
    const tsconfigPath = path.join(projectRoot, 'tsconfig.json');
    const hasTsconfig = await this.fileExists(tsconfigPath);

    if (hasTsconfig) {
      score += 0.3;
      evidence.push('tsconfig.json found');

      try {
        const content = await this.readFile(tsconfigPath);
        const tsconfig = JSON.parse(content);

        // Check for @/* path alias (common in Figma exports)
        if (tsconfig.compilerOptions?.paths?.['@/*']) {
          score += 0.2;
          evidence.push('Path aliases configured (typical of Figma exports)');
        }
      } catch (error) {
        // JSON parse error
      }
    }

    // Check for package-lock.json or yarn.lock
    const hasLockFile = (await this.fileExists(path.join(projectRoot, 'package-lock.json'))) ||
                        (await this.fileExists(path.join(projectRoot, 'yarn.lock')));

    if (hasLockFile) {
      score += 0.1;
      evidence.push('Dependency lock file found');
    }

    return { score: Math.min(score, 1.0), evidence };
  }

  /**
   * Check for CSS Modules pattern (Figma export signature)
   *
   * @private
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<{score: number, evidence: string[]}>}
   */
  async checkCSSModules(projectRoot) {
    const evidence = [];
    let score = 0;

    try {
      const srcDir = path.join(projectRoot, 'src');
      const allFiles = await this.getAllSourceFiles(srcDir);

      // Look for .module.css files
      const cssModuleFiles = allFiles.filter(f => f.endsWith('.module.css'));

      if (cssModuleFiles.length > 0) {
        score += 0.7;
        evidence.push(`CSS Modules pattern detected (${cssModuleFiles.length} files)`);

        // Check for CSS module imports in JSX files
        const jsxFiles = allFiles.filter(f => f.endsWith('.tsx') || f.endsWith('.jsx'));
        let moduleImportCount = 0;

        for (const file of jsxFiles.slice(0, 10)) {
          const content = await this.readFile(file);
          if (content && /import\s+(?:styles|className)\s+from\s+['"][^'"]*\.module\.css['"]/.test(content)) {
            moduleImportCount++;
          }
        }

        if (moduleImportCount > 0) {
          score += 0.3;
          evidence.push(`CSS Module imports detected (${moduleImportCount} files)`);
        }
      }
    } catch (error) {
      // Error checking CSS modules
    }

    return { score: Math.min(score, 1.0), evidence };
  }

  /**
   * Detect UI library from package.json
   *
   * @private
   * @param {Object|null} pkg - Parsed package.json
   * @returns {string|null} UI library name or null
   */
  detectUILibrary(pkg) {
    if (!pkg) return null;

    const deps = { ...pkg.dependencies, ...pkg.devDependencies };

    const uiLibraryMap = {
      '@mui/material': 'Material-UI',
      'antd': 'Ant Design',
      '@chakra-ui/react': 'Chakra UI',
      '@mantine/core': 'Mantine',
      'react-bootstrap': 'Bootstrap',
      'tailwindcss': 'Tailwind CSS'
    };

    for (const [depName, libName] of Object.entries(uiLibraryMap)) {
      if (deps[depName]) {
        return libName;
      }
    }

    return null;
  }

  /**
   * Detect build output directory from vite config
   *
   * @private
   * @param {string} projectRoot - Project root directory
   * @returns {Promise<string|null>} Build output directory or null
   */
  async detectBuildOutputDir(projectRoot) {
    try {
      const viteConfigTs = path.join(projectRoot, 'vite.config.ts');
      const viteConfigJs = path.join(projectRoot, 'vite.config.js');

      for (const configPath of [viteConfigTs, viteConfigJs]) {
        const content = await this.readFile(configPath);
        if (content) {
          // Try to extract outDir from config
          const match = content.match(/outDir\s*:\s*['"]([^'"]+)['"]/);
          if (match) {
            return match[1];
          }
        }
      }
    } catch (error) {
      // Error reading config
    }

    return 'dist'; // Default Vite output directory
  }
}

export default FigmaDetector;
